verifications.check_code:
opts={'A': 'DHLRW', 'B': 'DHLSX', 'C': 'EHLRX', 'D': 'EHLRW'}
s='ABC_FG_JK_MOPQ_TUV_Y'
def fill(o):
    it=iter(o); return ''.join(next(it) if c=='_' else c for c in s)
def ok(o):
    t=fill(o); return all(t[i]<t[i+1] for i in range(len(t)-1)) and len(t)==len(set(t)) and set('ABCDEFGHIJKLMNOPQRSTUVWXY')-set(t)=={'E','I','N','S','X'}
good=[k for k,v in opts.items() if ok(v)]
assert good==['A']

ant={"Conceal":"Disclose","Identical":"Distinct"}
syn={"Similar","Analogous","Homogeneous"}
opts={"A":"Similar","B":"Analogous","C":"Distinct","D":"Homogeneous"}
ans=ant["Identical"]
assert ans==opts["C"]
for k in "ABD": assert opts[k]!=ans and opts[k] in syn

ant={'Conceal':'Disclose','Identical':{'Distinct'}}
opts={"A":"Similar","B":"Analogous","C":"Distinct","D":"Homogeneous"}
syn={'Similar','Analogous','Homogeneous'}
good=[k for k,v in opts.items() if v in ant['Identical'] and v not in syn]
assert good==['C']

opts={'A': 62, 'B': 64, 'C': 58, 'D': 71}
v=11*8+78/6-37
assert v==opts['B'] and all(v!=opts[k] for k in 'ACD')

P=["TL","TM","TR","M","BM","BR"]
def fig(s): return dict(zip(P,s.split()))
F=[fig("S P F V N C"),fig("F V S N C P"),fig("V F N C P S"),fig("N C V P S F")]
def trans(a,b):
    inv={v:k for k,v in b.items()}
    return {pos:inv[a[pos]] for pos in P}
t=[trans(F[i],F[i+1]) for i in range(3)]
assert t[0]==t[2]
nxt={t[1][pos]:F[3][pos] for pos in P}
opts={"A":fig("F P N S C V"),"B":fig("C N P S F V"),"C":fig("C N F V P S"),"D":fig("V N C F P S")}
good=[k for k,v in opts.items() if v==nxt]
assert good==["B"]

rel={}
# T father of H; I brother of T
father={"H":"T"}; brother_of={"I":"T"}
r="Father’s brother" if brother_of["I"]==father["H"] else None
opts={"A":"Brother","B":"Father’s brother","C":"Father’s sister","D":"Father’s father"}
assert r==opts["B"]
for k in "ACD": assert r!=opts[k]

# symbolic chain: I brother of T, T father of H => I is paternal uncle of H
rel={('brother','father'):"Father’s brother"}
opts={"A":"Brother","B":"Father’s brother","C":"Father’s sister","D":"Father’s father"}
r=rel[('brother','father')]
assert r==opts['B'] and all(r!=opts[k] for k in 'ACD')

cw={"TL":"TR","TR":"BR","BR":"BL","BL":"TL"}
