      "B":({"TL":"triangle","TR":"star","BL":"square","BR":"circle"},"E"),
      "C":({"TL":"square","TR":"triangle","BL":"circle","BR":"star"},"S"),
      "D":({"TL":"square","TR":"triangle","BL":"circle","BR":"star"},"SW")}
