corners=['TL','TR','BR','BL']
f1={'TL':'tri','TR':'star','BR':'circ','BL':'sq'}
def rot(f): return {corners[(corners.index(k)+1)%4]:v for k,v in f.items()}
f=f1
for _ in range(4): f=rot(f)
arrow=(0+45*4)%360
opts={'A':({'TL':'tri','TR':'star','BL':'sq','BR':'circ'},180),'B':({'TL':'tri','TR':'star','BL':'sq','BR':'circ'},90),'C':({'TL':'sq','TR':'tri','BL':'circ','BR':'star'},180),'D':({'TL':'sq','TR':'tri','BL':'circ','BR':'star'},225)}
assert [k for k,v in opts.items() if v==(f,arrow)]==['A']

from itertools import permutations
res=set()
for p in permutations(["M","F","H"]):
    cyc=["G"]+list(p)
    c=lambda a,b: cyc[(cyc.index(a)+1)%4]==b
    if c("G","M") and c("F","H"): res.add(cyc[2])
assert res=={"F"}
ans=res.pop()
opts={"A":"S","B":"F","C":"H","D":"M"}
assert ans==opts["B"]
for k in "ACD": assert ans!=opts[k]

expr="7 + 4 ÷18 – 3 × 2"
m={"÷":"-","–":"/","×":"+","+":"*"}
v=eval("".join(m.get(c,c) for c in expr))
opts={"A":18,"B":16,"C":24,"D":20}
assert v==opts["C"]
for k in "ABD": assert v!=opts[k]

